namespace sv_2cf0a449b0a1408fb866e9af12cc23ae.Services;

public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "warehouse-a";
    public string SelectedWarehouseName { get; private set; } = "Warehouse A";

    public event Action? OnChange;

    public static readonly (string Id, string Name)[] AvailableWarehouses =
    [
        ("warehouse-a", "Warehouse A"),
        ("warehouse-b", "Warehouse B"),
        ("warehouse-c", "Warehouse C"),
        ("warehouse-d", "Warehouse D"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        var match = AvailableWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (match == default) return;

        SelectedWarehouseId = match.Id;
        SelectedWarehouseName = match.Name;
        OnChange?.Invoke();
    }
}

namespace sv_2cf0a449b0a1408fb866e9af12cc23ae.Services;

public class InventoryAlertService
{
    private static readonly Random _random = new();

    public int CurrentLowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query returning a random number between 0 and 15
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    public void UpdateCount(int newCount)
    {
        CurrentLowStockCount = newCount;
        OnAlertCountChanged?.Invoke();
    }
}

