@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable

@using sv_2cf0a449b0a1408fb866e9af12cc23ae.Services

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse: @Warehouse.SelectedWarehouseName</h5>
        <p class="card-text">
            Low-stock alerts:
            <span class="badge bg-warning text-dark fs-5">@AlertService.CurrentLowStockCount</span>
            items below minimum level
        </p>
        <p class="text-muted small">Polling every 10 seconds. Last checked: @_lastChecked?.ToString("HH:mm:ss")</p>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private DateTime? _lastChecked;

    protected override void OnInitialized()
    {
        Warehouse.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertChanged;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            StartPolling();
        }
    }

    private void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse
        StopPolling();
        StartPolling();
        InvokeAsync(StateHasChanged);
    }

    private void OnAlertChanged() => InvokeAsync(StateHasChanged);

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        var token = _cts.Token;
        _ = PollAsync(token);
    }

    private async Task PollAsync(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            try
            {
                var count = await AlertService.GetLowStockCountAsync(Warehouse.SelectedWarehouseId);
                _lastChecked = DateTime.Now;
                // Update the shared service — this notifies ALL subscribers (sidebar badge, etc.)
                AlertService.UpdateCount(count);
            }
            catch (ObjectDisposedException)
            {
                break;
            }

            try
            {
                await Task.Delay(TimeSpan.FromSeconds(10), token);
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        StopPolling();
        Warehouse.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertChanged;
    }
}

